#!/usr/bin/env python3
"""Regenerate the conformance fixtures in this directory.

The fixtures are committed; this script exists so the hex encodings are derived
rather than hand-written, and so adding a case is a code edit rather than a
manual hex-assembly exercise.

Stdlib only — run it with any python3:
    python3 testdata/conformance/gen_fixtures.py

(The scaffold's version imported eth_abi to build the ABI-encoded SAY_GOODBYE
payload. GET_FEED's request envelope is a single static bytes21 in a 32-byte
word, so it is assembled with a plain ljust rather than reintroducing eth-abi.
If a future op takes a dynamic tuple, reintroduce eth-abi in a venv.)

Each fixture is a single request/response pair asserted against the extension by
scripts/test-conformance.sh. See docs/extension-contract.md.

The fixtures are ORDER-DEPENDENT and share one process: counters accumulate and
the final fixture asserts the resulting state. index.json fixes the order.
"""

from __future__ import annotations

import json
import pathlib

HERE = pathlib.Path(__file__).parent

ACTION_ID = "0x" + "11" * 32
TEE_ID = "0x" + "22" * 20
VERSION = "0.1.0"

OP_TYPE = "TEE_ORACLE"
OP_COMMAND = "GET_FEED"

# The instruction timestamp. The scaffold handler echoes this as observedAt,
# which is what keeps these fixtures byte-reproducible. When the real handler
# stamps observedAt from the observation window instead, the exact-match
# assertion on `data` below has to become a structural one.
TIMESTAMP = 1700000000

# $1.00 at config.PriceDecimals (8).
STUB_PRICE = "100000000"
PRICE_DECIMALS = 8


def b32(s: str) -> str:
    b = s.encode("utf-8")
    return "0x" + b.ljust(32, b"\x00").hex()


def to_hex(b: bytes) -> str:
    return "0x" + b.hex()


def action(op_type: str, op_command: str, original: bytes, action_id: str = ACTION_ID) -> dict:
    """Build a POST /action body in the exact shape tee-node sends."""
    data_fixed = {
        "instructionId": action_id,
        "teeId": TEE_ID,
        "timestamp": TIMESTAMP,
        "rewardEpochId": 42,
        "opType": b32(op_type),
        "opCommand": b32(op_command),
        "cosigners": [],
        "cosignersThreshold": 0,
        "originalMessage": to_hex(original),
        "additionalFixedMessage": "0x",
    }
    return {
        "data": {
            "id": action_id,
            "type": "instruction",
            "submissionTag": "submit",
            "message": to_hex(json.dumps(data_fixed).encode("utf-8")),
        },
        "additionalVariableMessages": [],
        "timestamps": [],
        "additionalActionData": "0x",
        "signatures": [],
    }


# The request envelope requestFeedUpdate() carries, mirroring
# GET_FEED_REQUEST_V1 / abi.encode(FeedUpdateRequest{feedId}) upstream and
# report.DecodeFeedRequest in the extension.
#
# It used to be a single 0x01 byte; when one sender started serving several
# feeds it became the ABI-encoded FeedUpdateRequest — the 21-byte feed id in a
# single 32-byte word (bytes21 is static, so it encodes inline, left-aligned and
# right-padded). The handler requires exactly this value for the feed it serves,
# so an unrecognised envelope — or a request for another feed — is refused
# rather than ignored.
FEED_ID = bytes.fromhex("20555344582f555344000000000000000000000000")  # 21 bytes: 0x20 + "USDX/USD"
GET_FEED_REQUEST = FEED_ID.ljust(32, b"\x00")


def get_feed(original: bytes = GET_FEED_REQUEST) -> dict:
    """A GET_FEED action carrying the ABI-encoded FeedUpdateRequest envelope."""
    return action(OP_TYPE, OP_COMMAND, original)


# A direct action's id is generated by the proxy, not taken from a chain.
DIRECT_ACTION_ID = "0x" + "33" * 32

# failure.WrongActionType, verbatim. Log is world-readable and the classes are a
# closed vocabulary, so it is asserted rather than prefix-matched.
WRONG_ACTION_TYPE = "command arrived over the wrong action type"


def direct_action(op_type: str, op_command: str, message: bytes,
                  action_id: str = DIRECT_ACTION_ID) -> dict:
    """Build a POST /action body for a DIRECT action, as the proxy sends it.

    The inner envelope is a DirectInstruction, NOT a DataFixed: its payload field
    is "message" and it carries no instructionId, teeId or timestamp. Encoding
    this as a DataFixed is a silent failure rather than a loud one — encoding/json
    drops the unknown field, so the handler sees an empty payload — which is
    exactly how the extension shipped unable to read a real direct action.

    Only GET_READINESS and SET_SECRET are served this way; GET_FEED is refused
    over it, which fixture 13 pins.
    """
    direct_instruction = {
        "opType": b32(op_type),
        "opCommand": b32(op_command),
        "message": to_hex(message),
    }
    return {
        "data": {
            "id": action_id,
            "type": "direct",
            "submissionTag": "submit",
            "message": to_hex(json.dumps(direct_instruction).encode("utf-8")),
        },
        "additionalVariableMessages": [],
        "timestamps": [],
        "additionalActionData": "0x",
        "signatures": [],
    }


def json_msg(obj) -> bytes:
    """Serialize compactly, with no whitespace.

    This matters for expected ActionResult.data: the comparison is byte-exact,
    because tee-node hashes `data` (ActionResult.Hash computes keccak256 over
    it) and signs the result. Go's encoding/json emits compact output with
    struct-declaration field order, so key order here must match the field order
    in pkg/types.GetPriceResponse.
    """
    return json.dumps(obj, separators=(",", ":")).encode("utf-8")


PRICE_PAYLOAD = json_msg({
    "price": STUB_PRICE,
    "decimals": PRICE_DECIMALS,
    "observedAt": TIMESTAMP,
})


FIXTURES: list[dict] = [
    {
        "name": "01-get-feed-success",
        "description": "GET_FEED with the ABI-encoded FeedUpdateRequest envelope returns the price, decimals and observedAt",
        "request": {"method": "POST", "path": "/action", "body": get_feed()},
        "expect": {
            "status": 200,
            "json": {
                "id": ACTION_ID,
                "submissionTag": "submit",
                "status": 1,
                "log": "ok",
                "opType": b32(OP_TYPE),
                "opCommand": b32(OP_COMMAND),
                # hexutil.Bytes with no omitempty marshals as "0x", never absent.
                "additionalResultStatus": "0x",
                # Plain string, NOT bytes32 — contract §4.4.
                "version": VERSION,
                "data": to_hex(PRICE_PAYLOAD),
            },
        },
    },
    {
        "name": "02-get-feed-is-deterministic",
        "description": (
            "A second GET_FEED returns an identical payload. Unlike the scaffold's "
            "greeting counter, the price is a function of observed inputs, not of how "
            "many times it has been asked — nothing in the payload may drift per call."
        ),
        "request": {"method": "POST", "path": "/action", "body": get_feed()},
        "expect": {
            "status": 200,
            "json_subset": {"status": 1, "data": to_hex(PRICE_PAYLOAD)},
        },
    },
    {
        "name": "03-get-feed-rejects-payload",
        "description": (
            "requestFeedUpdate() sends exactly the ABI-encoded FeedUpdateRequest. Any "
            "other message — here a JSON blob that is neither 32 bytes nor a valid "
            "feed id — is a handler error, not silently ignored: HTTP 200, status 0, "
            "no data."
        ),
        "request": {"method": "POST", "path": "/action",
                    "body": get_feed(json_msg({"unexpected": "payload"}))},
        "expect": {
            "status": 200,
            # data is still emitted, as "0x" — the Go struct has no omitempty.
            "json_subset": {"status": 0, "data": "0x"},
            "log_prefix": "error: ",
        },
    },
    {
        "name": "04-unknown-op-type",
        "description": "An unrouted opType is 501 with a plain-text body",
        "request": {"method": "POST", "path": "/action",
                    "body": action("NOT_A_REAL_TYPE", OP_COMMAND, b"")},
        # Go names the received vs expected opType, which is more useful than a
        # bare string. The status code is contractual; the wording is not.
        "expect": {"status": 501, "text_contains": "unsupported op type"},
    },
    {
        "name": "05-unknown-op-command",
        "description": "A known opType with an unrouted opCommand is also 501",
        "request": {"method": "POST", "path": "/action",
                    "body": action(OP_TYPE, "NOT_A_COMMAND", b"")},
        "expect": {"status": 501, "text_contains": "unsupported op command"},
    },
    {
        "name": "06-invalid-action-json",
        "description": "A body that is not JSON is 400",
        "request": {"method": "POST", "path": "/action", "raw_body": "not json at all"},
        "expect": {"status": 400},
    },
    {
        "name": "07-invalid-hex-in-message",
        "description": "A non-hex data.message is 400",
        "request": {
            "method": "POST", "path": "/action",
            "body": {"data": {"id": ACTION_ID, "type": "instruction",
                              "submissionTag": "submit", "message": "0xZZZZ"}},
        },
        "expect": {"status": 400},
    },
    {
        "name": "08-message-not-datafixed",
        "description": "A valid-hex message that is not DataFixed JSON is 400",
        "request": {
            "method": "POST", "path": "/action",
            "body": {"data": {"id": ACTION_ID, "type": "instruction",
                              "submissionTag": "submit", "message": to_hex(b"not json")}},
        },
        "expect": {"status": 400},
    },
    {
        "name": "09-get-action-not-allowed",
        "description": "GET /action is 405",
        "request": {"method": "GET", "path": "/action"},
        "expect": {"status": 405},
    },
    {
        "name": "10-post-state-not-allowed",
        "description": "POST /state is 405",
        "request": {"method": "POST", "path": "/state", "raw_body": ""},
        "expect": {"status": 405},
    },
    {
        "name": "11-unknown-path",
        "description": "An unknown path is 404",
        "request": {"method": "GET", "path": "/does-not-exist"},
        "expect": {"status": 404},
    },
    {
        "name": "12-get-state",
        "description": (
            "GET /state returns bytes32 stateVersion and operational state only. "
            "Two successes and one rejected payload have accumulated by now, and the "
            "error class from fixture 03 is still the last one recorded. "
            "This is a whole-body exact match on purpose: spec §4.1 makes /state "
            "public and attested, so an accidentally added field carrying a supply or "
            "reserve figure must fail the suite rather than slip through."
        ),
        "request": {"method": "GET", "path": "/state"},
        "expect": {
            "status": 200,
            "json": {
                # Asymmetric with ActionResult.version by design — contract §4.5.
                "stateVersion": b32(VERSION),
                "state": {
                    # Stub mode has no provisioner, so provisioning has not
                    # happened and every flag is false. In production this is
                    # what distinguishes "never configured" from "configured but
                    # a source is down" — see the findings doc §14.
                    "readiness": {
                        "endpointsSet": False,
                        # Empty until SET_ENDPOINTS lands. Once set, this is
                        # keccak256 of the payload and must equal the hash in
                        # the EndpointsSet event.
                        "endpointsHash": "",
                        # The admin signer set, published separately by
                        # SET_ADMINS and hashed the same way. Both halves are
                        # required before the machine reads as configured.
                        "adminsSet": False,
                        "adminsHash": "",
                        "ready": False,
                        "missingSecretRefs": [],
                    },
                    "lastPrice": STUB_PRICE,
                    "lastDecimals": PRICE_DECIMALS,
                    "lastObservedAt": TIMESTAMP,
                    "updateCount": 2,
                    "failureCount": 1,
                    "lastErrorClass": "source_invalid",
                    "sourceHealth": {},
                },
            },
        },
    },
    {
        "name": "13-get-feed-refused-over-direct",
        "description": (
            "GET_FEED is an on-chain instruction and nothing else. Serving it over "
            "the direct channel would hand the same signed update to anyone holding "
            "the proxy API key, free and unrecorded, so a direct GET_FEED is refused "
            "with the wrong-action-type class rather than answered. "
            "The envelope here is a DirectInstruction rather than a DataFixed, which "
            "is the shape the proxy really sends: parsing one as the other does not "
            "error, it yields an empty payload, so this also pins that the refusal "
            "comes from the CHANNEL check and not from an accidentally empty message. "
            "Deliberately last — the fixtures share one process and 12-get-state "
            "asserts the counters exactly, so anything inserted before it moves them."
        ),
        "request": {"method": "POST", "path": "/action",
                    "body": direct_action(OP_TYPE, OP_COMMAND, GET_FEED_REQUEST)},
        "expect": {
            "status": 200,
            "json": {
                # The proxy's action id, which stands in for the instruction id a
                # direct action does not have.
                "id": DIRECT_ACTION_ID,
                "submissionTag": "submit",
                "status": 0,
                "log": "error: " + WRONG_ACTION_TYPE,
                "opType": b32(OP_TYPE),
                "opCommand": b32(OP_COMMAND),
                "additionalResultStatus": "0x",
                "version": VERSION,
                "data": "0x",
            },
        },
    },
]


def main() -> None:
    index = []
    for f in FIXTURES:
        path = HERE / f"{f['name']}.json"
        path.write_text(json.dumps(f, indent=2) + "\n")
        index.append(f["name"])

    (HERE / "index.json").write_text(json.dumps({"fixtures": index}, indent=2) + "\n")

    # Drop fixtures that are no longer generated. Without this, renaming a case
    # leaves the old file behind: harmless to the suite, which reads index.json,
    # but it reads as a live fixture to anyone browsing the directory.
    keep = {f"{name}.json" for name in index} | {"index.json"}
    removed = []
    for path in sorted(HERE.glob("*.json")):
        if path.name not in keep:
            path.unlink()
            removed.append(path.name)

    print(f"wrote {len(index)} fixtures + index.json to {HERE}")
    if removed:
        print(f"removed {len(removed)} stale fixture(s): {', '.join(removed)}")


if __name__ == "__main__":
    main()
